/* Avisos de la ficha y del cuaderno del profesional. */
(function () {
  if (!window.BBL || !BBL.extend) return;
  BBL.extend({
    es:{"pp_cl_aviso":"Lo que apuntes de cada clienta forma parte de su pasaporte de belleza (salvo las notas que marques como tuyas). Nunca se publica.","pp_clientas_sub":"Tu ficha de cada una, que también forma parte de su pasaporte de belleza. Nunca se publica.","pp_fi_aviso":"Esta ficha forma parte del pasaporte de belleza de la clienta: la ve ella y, si lo permite, sus otras profesionales. Nunca se publica. En el cuaderno puedes dejar notas sólo para ti."},
    en:{"pp_cl_aviso":"What you note about each client is part of her beauty passport (except notes you mark as yours). It's never published.","pp_clientas_sub":"Your record of each client, which is also part of her beauty passport. It's never published.","pp_fi_aviso":"This record is part of the client's beauty passport: she sees it and, if she allows, her other professionals. It's never published. In the notebook you can leave notes just for you."},
    pt:{"pp_cl_aviso":"O que registas de cada cliente faz parte do passaporte de beleza dela (exceto as notas que marques como tuas). Nunca é publicado.","pp_clientas_sub":"A tua ficha de cada uma, que também faz parte do passaporte de beleza dela. Nunca é publicada.","pp_fi_aviso":"Esta ficha faz parte do passaporte de beleza da cliente: vê-a ela e, se autorizar, as outras profissionais dela. Nunca é publicada. No caderno podes deixar notas só para ti."},
    fr:{"pp_cl_aviso":"Ce que tu notes sur chaque cliente fait partie de son passeport beauté (sauf les notes que tu marques comme personnelles). Ce n'est jamais publié.","pp_clientas_sub":"Ta fiche de chacune, qui fait aussi partie de son passeport beauté. Elle n'est jamais publiée.","pp_fi_aviso":"Cette fiche fait partie du passeport beauté de la cliente : elle la voit, ainsi que ses autres professionnelles si elle l'autorise. Elle n'est jamais publiée. Dans le carnet, tu peux laisser des notes rien qu'à toi."},
    de:{"pp_cl_aviso":"Was du über jede Kundin notierst, gehört zu ihrem Beauty-Pass (außer Notizen, die du als privat markierst). Es wird nie veröffentlicht.","pp_clientas_sub":"Deine Karte zu jeder Kundin, die auch Teil ihres Beauty-Passes ist. Sie wird nie veröffentlicht.","pp_fi_aviso":"Diese Karte gehört zum Beauty-Pass der Kundin: Sie sieht sie und, wenn sie es erlaubt, ihre anderen Profis. Sie wird nie veröffentlicht. Im Notizbuch kannst du private Notizen hinterlassen."},
    it:{"pp_cl_aviso":"Ciò che annoti di ogni cliente fa parte del suo passaporto di bellezza (tranne le note che segni come tue). Non viene mai pubblicato.","pp_clientas_sub":"La tua scheda di ognuna, che fa parte anche del suo passaporto di bellezza. Non viene mai pubblicata.","pp_fi_aviso":"Questa scheda fa parte del passaporto di bellezza della cliente: la vede lei e, se lo permette, le sue altre professioniste. Non viene mai pubblicata. Nel quaderno puoi lasciare note solo per te."},
    nl:{"pp_cl_aviso":"Wat je over elke klant noteert hoort bij haar beautypaspoort (behalve notities die je als privé markeert). Het wordt nooit gepubliceerd.","pp_clientas_sub":"Jouw kaart van elke klant, die ook bij haar beautypaspoort hoort. Hij wordt nooit gepubliceerd.","pp_fi_aviso":"Deze kaart hoort bij het beautypaspoort van de klant: zij ziet hem en, als ze het toestaat, haar andere professionals. Hij wordt nooit gepubliceerd. In het notitieboek kun je notities alleen voor jezelf maken."},
    pl:{"pp_cl_aviso":"To, co zapisujesz o każdej klientce, jest częścią jej paszportu urody (poza notatkami oznaczonymi jako twoje). Nigdy nie jest publikowane.","pp_clientas_sub":"Twoja karta każdej klientki, która jest też częścią jej paszportu urody. Nigdy nie jest publikowana.","pp_fi_aviso":"Ta karta jest częścią paszportu urody klientki: widzi ją ona i, jeśli pozwoli, jej inne specjalistki. Nigdy nie jest publikowana. W notesie możesz zostawić notatki tylko dla siebie."},
    el:{"pp_cl_aviso":"Ό,τι σημειώνεις για κάθε πελάτισσα είναι μέρος του διαβατηρίου ομορφιάς της (εκτός από σημειώσεις που ορίζεις ως δικές σου). Δεν δημοσιεύεται ποτέ.","pp_clientas_sub":"Η καρτέλα σου για την καθεμία, που είναι και μέρος του διαβατηρίου ομορφιάς της. Δεν δημοσιεύεται ποτέ.","pp_fi_aviso":"Αυτή η καρτέλα είναι μέρος του διαβατηρίου ομορφιάς της πελάτισσας: τη βλέπει εκείνη και, αν το επιτρέψει, οι άλλες επαγγελματίες της. Δεν δημοσιεύεται ποτέ. Στο τετράδιο μπορείς να αφήνεις σημειώσεις μόνο για σένα."},
    hu:{"pp_cl_aviso":"Amit egy ügyfélről feljegyzel, a szépségútlevelének része (kivéve a sajátként jelölt jegyzeteket). Soha nem kerül nyilvánosságra.","pp_clientas_sub":"Az adatlapod minden ügyfélről, amely a szépségútlevelének is része. Soha nem kerül nyilvánosságra.","pp_fi_aviso":"Ez az adatlap az ügyfél szépségútlevelének része: ő látja, és ha engedi, a többi szakembere is. Soha nem kerül nyilvánosságra. A füzetbe csak magadnak szóló jegyzeteket is írhatsz."},
    ru:{"pp_cl_aviso":"Ваши записи о каждой клиентке — часть её паспорта красоты (кроме заметок, отмеченных как личные). Никогда не публикуются.","pp_clientas_sub":"Ваша карта каждой клиентки — она же часть её паспорта красоты. Никогда не публикуется.","pp_fi_aviso":"Эта карта — часть паспорта красоты клиентки: её видит она и, с её разрешения, другие мастера. Она никогда не публикуется. В блокноте можно оставлять заметки только для себя."},
    ar:{"pp_cl_aviso":"ما تسجلينه عن كل عميلة جزء من جواز جمالها (عدا الملاحظات التي تحددينها كخاصة). لا يُنشر أبداً.","pp_clientas_sub":"بطاقتك لكل عميلة، وهي أيضاً جزء من جواز جمالها. لا تُنشر أبداً.","pp_fi_aviso":"هذه البطاقة جزء من جواز جمال العميلة: تراها هي، ومحترفاتها الأخريات إن سمحت. لا تُنشر أبداً. في الدفتر يمكنكِ ترك ملاحظات خاصة بكِ."},
    zh:{"pp_cl_aviso":"你为每位客户记录的内容是她美丽护照的一部分（标记为私人的备注除外）。绝不会公开。","pp_clientas_sub":"你为每位客户建立的档案，也是她美丽护照的一部分。绝不会公开。","pp_fi_aviso":"此档案是客户美丽护照的一部分：她本人可见，经她允许其他美容师也可见。绝不会公开。你可以在笔记本中留下仅自己可见的备注。"},
    ja:{"pp_cl_aviso":"各お客さまについての記録は、その方のビューティーパスポートの一部です（自分用にしたメモを除く）。公開されることはありません。","pp_clientas_sub":"お客さまごとのカルテは、その方のビューティーパスポートの一部でもあります。公開されることはありません。","pp_fi_aviso":"このカルテはお客さまのビューティーパスポートの一部です。本人と、許可があれば他の担当者が閲覧できます。公開されることはありません。ノートには自分だけのメモも残せます。"},
    ko:{"pp_cl_aviso":"각 고객에 대한 기록은 고객 뷰티 여권의 일부입니다(나만 보기로 표시한 메모 제외). 공개되지 않습니다.","pp_clientas_sub":"고객별 카드이며, 고객 뷰티 여권의 일부이기도 합니다. 공개되지 않습니다.","pp_fi_aviso":"이 카드는 고객 뷰티 여권의 일부입니다. 고객 본인과, 허락하면 다른 전문가가 볼 수 있습니다. 공개되지 않습니다. 노트에는 나만 보는 메모를 남길 수 있습니다."},
    sv:{"pp_cl_aviso":"Det du antecknar om varje kund ingår i hennes skönhetspass (utom anteckningar du markerar som dina). Det publiceras aldrig.","pp_clientas_sub":"Ditt kort för varje kund, som också ingår i hennes skönhetspass. Det publiceras aldrig.","pp_fi_aviso":"Det här kortet ingår i kundens skönhetspass: hon ser det och, om hon tillåter, hennes andra yrkespersoner. Det publiceras aldrig. I anteckningsboken kan du lämna anteckningar bara för dig."}
  });
})();

